// Every Plot3DView capability, in the order the declaring class takes them.
template <typename Declaring>
struct Plot3DViewCapabilities : public Plot3DViewShowPanesCapability<Declaring>,
                                public Plot3DViewShowGridCapability<Declaring>,
                                public Plot3DViewShowAxesCapability<Declaring>,
                                public Plot3DViewWheelZoomCapability<Declaring>,
                                public Plot3DViewLabelsAlongAxisCapability<Declaring> {};

